"""The Capability roster (能力名冊): one declaration of what a Service may do.

The engine used to decide per Service by comparing ``cbTS.imeDirName`` against
an inline name tuple, copied once per Intelligent select (智慧選字) call site.
This module is the single seam for that decision: the roster is the data,
``has()`` and ``menu_items_for()`` are the interface, and every engine site
plus the settings UI reads it. A Service outside the roster gets neither the
behaviour nor its 功能開關 menu items, whatever its own configuration package
says. Adding a capability is an entry in ``CAPABILITIES`` and (if it owns
功能開關 items) ``MENU_ITEMS``, not a new branch in the engine.
"""

INTELLIGENT_SELECT = "intelligentSelect"  # the capability token

# The Capability roster: capabilities.CAPABILITIES maps a cinbase Service
# directory name to the capabilities it holds.
CAPABILITIES = {
    "chedayi": frozenset({INTELLIGENT_SELECT}),
    "chebihua": frozenset({INTELLIGENT_SELECT}),
}

# The 功能開關 item names each capability contributes, in menu order.
MENU_ITEMS = {
    INTELLIGENT_SELECT: ("intelligentSelect", "intelligentSelectRecent",
                         "intelligentSelectContext"),
}

# The 功能開關 items the roster-driven branch builds from, in menu order: they
# are the whole menu of an un-rostered Service only in the engine's own literal
# below; a rostered Service gets these plus the items of each capability it
# holds, spliced in right after MENU_ANCHOR_ITEM.
COMMON_MENU_ITEMS = ("fullShapeSymbols", "easySymbolsWithShift",
                     "autoClearCompositionChar", "playSoundWhenNonCand",
                     "showPhrase", "sortByPhrase", "supportWildcard",
                     "imeReverseLookup", "homophoneQuery")
MENU_ANCHOR_ITEM = "sortByPhrase"


def capabilities_for(ime_dir_name):
    """The frozenset of capabilities the roster grants ``ime_dir_name``;
    empty for a Service outside the roster."""
    return CAPABILITIES.get(ime_dir_name, frozenset())


def has(ime_dir_name, capability):
    """True when the roster grants ``capability`` to ``ime_dir_name``."""
    return capability in capabilities_for(ime_dir_name)


def has_menu_items(ime_dir_name):
    """True when ``ime_dir_name`` holds a capability that contributes its own
    功能開關 items, i.e. when its menu is roster-driven rather than the plain one."""
    return any(has(ime_dir_name, capability) for capability in MENU_ITEMS)


def menu_items_for(ime_dir_name):
    """The ordered 功能開關 item names for ``ime_dir_name``: the common items,
    with the items of each held capability spliced in after MENU_ANCHOR_ITEM
    in ``MENU_ITEMS`` declaration order."""
    items = list(COMMON_MENU_ITEMS)
    anchor = items.index(MENU_ANCHOR_ITEM) + 1
    for capability, names in MENU_ITEMS.items():
        if has(ime_dir_name, capability):
            items[anchor:anchor] = names
            anchor += len(names)
    return tuple(items)
